input.command:
$inPath = "C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage\data\_tmp\todo_batch_14.csv"
$outPath = "C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage\config\model_labels\batch_14.csv"

$inRows = Import-Csv $inPath
$outRows = Import-Csv $outPath

Write-Output "Input rows: $($inRows.Count)"
Write-Output "Output rows: $($outRows.Count)"

$inKeys = $inRows | Select-Object -ExpandProperty key
$outKeys = $outRows | Select-Object -ExpandProperty key

$inSet = [System.Collections.Generic.HashSet[string]]::new([string[]]$inKeys)
$outSet = [System.Collections.Generic.HashSet[string]]::new([string[]]$outKeys)

$missing = $inKeys | Where-Object { -not $outSet.Contains($_) }
$extra = $outKeys | Where-Object { -not $inSet.Contains($_) }
$dupOut = $outKeys | Group-Object | Where-Object { $_.Count -gt 1 }

Write-Output "Missing from output: $($missing.Count)"
Write-Output "Extra in output (not in input): $($extra.Count)"
Write-Output "Duplicate keys in output: $($dupOut.Count)"
if ($missing.Count -gt 0) { $missing | ForEach-Object { Write-Output "MISSING: $_" } }
if ($extra.Count -gt 0) { $extra | ForEach-Object { Write-Output "EXTRA: $_" } }
if ($dupOut.Count -gt 0) { $dupOut | ForEach-Object { Write-Output "DUP: $($_.Name) x$($_.Count)" } }

$validRoutes = @("skip","already in Zotero","paper to Zotero","book","atomize","transcribe","catalog only")
$validTiers = @("B","C")
$validDisciplines = @(
 "Strength and power","Periodization and programming","Speed and sprint","Conditioning and energy systems",
 "Rehab and return to play","Injury risk and prevention","Load monitoring and GPS","Testing and assessment",
 "Recovery and sleep","Nutrition and body composition","Anatomy, physiology and biomechanics",
 "Coaching, skill acquisition and constraints-led approach","Data, technology and reporting",
 "Leadership, culture and psychology","Female athlete","Youth and development"
)

$badRoute = $outRows | Where-Object { $validRoutes -notcontains $_.route }
$badTier = $outRows | Where-Object { $validTiers -notcontains $_.tier }
$badCandidate = $outRows | Where-Object { $_.candidate -ne "yes" -and $_.candidate -ne "no" }
$badTierRoute = $outRows | Where-Object { ($_.route -eq "skip" -and $_.tier -ne "C") -or ($_.route -ne "skip" -and $_.tier -ne "B") }

Write-Output "Bad route count: $($badRoute.Count)"
Write-Output "Bad tier count: $($badTier.Count)"
Write-Output "Bad candidate count: $($badCandidate.Count)"
Write-Output "Tier/route mismatch count: $($badTierRoute.Count)"

$badDisc = @()
foreach ($r in $outRows) {
  if ($r.disciplines -and $r.disciplines.Trim() -ne "") {
    $parts = $r.disciplines -split ";" | ForEach-Object { $_.Trim() }
    foreach ($p in $parts) {
      if ($validDisciplines -notcontains $p) { $badDisc += "$($r.key): [$p]" }
    }
  }
}
Write-Output "Bad discipline tokens: $($badDisc.Count)"
$badDisc | ForEach-Object { Write-Output $_ }

$candYes = $outRows | Where-Object { $_.candidate -eq "yes" }
Write-Output "Candidate=yes count: $($candYes.Count)"
$candYes | ForEach-Object { Write-Output "CANDIDATE: $($_.key) | $($_.route) | $($_.reason)" }

Write-Output "--- tier counts ---"
$outRows | Group-Object tier | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }
Write-Output "--- route counts ---"
$outRows | Group-Object route | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }

Write-Output "--- dash check in reason ---"
$dashRows = $outRows | Where-Object { $_.reason -match "[–—]" }
Write-Output "Rows with en/em dash in reason: $($dashRows.Count)"

